import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.wxcks8ca.js";var i=JSON.parse(`{"title":"使用目标模式","description":"","frontmatter":{},"headers":[],"relativePath":"kimi-code-cli/guides/goals.md","filePath":"zh/kimi-code-cli/guides/goals.md"}`),a={name:`kimi-code-cli/guides/goals.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="使用目标模式" tabindex="-1">使用目标模式 <a class="header-anchor" href="#使用目标模式" aria-label="Permalink to “使用目标模式”">​</a></h1><p>目标（goal）让 Kimi Code 在多个轮次中持续朝一个明确结果工作——不同于普通提示词只说&quot;下一步做什么&quot;，目标说的是&quot;最终要达成什么状态&quot;。当任务有清晰终点，但下一步取决于 Agent 工作中发现的信息时，使用 <code>/goal</code>，例如：修复一批失败的测试、追踪并修复构建失败的根因。</p><h2 id="开始目标" tabindex="-1">开始目标 <a class="header-anchor" href="#开始目标" aria-label="Permalink to “开始目标”">​</a></h2><p>在 <code>/goal</code> 命令后写目标：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 修复项目的</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GitHub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 的</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> issues</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 中列出的</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bug</span></span></code></pre></div><p>Kimi Code 会保存该目标，把它作为下一条用户消息发送，并进入目标模式。每个轮次结束后，它会检查目标是「完成（<code>complete</code>）」、「阻塞（<code>blocked</code>）」、「暂停（<code>paused</code>）」，还是仍然「活跃（<code>active</code>）」。</p><p>好的目标应当说清楚具体的完成条件：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 修复所有标签关于结算系统的回退的漏洞，为每个修复新增或更新测试，最后运行所有有关结算的测试套件</span></span></code></pre></div><p>避免只写宽泛方向：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 找出这个代码库中的所有</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bug</span></span></code></pre></div><p>这个目标没有说明什么算成功、要检查什么，也没有说明其他的停止条件。Agent 可能会因为一些问题立刻进入「阻塞（<code>blocked</code>）」状态，也可能工作得比预期更久。</p><h3 id="何时使用目标模式" tabindex="-1">何时使用目标模式 <a class="header-anchor" href="#何时使用目标模式" aria-label="Permalink to “何时使用目标模式”">​</a></h3><ol><li><p>对有明确终点和可验证证据的工作使用目标模式。</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 修复所有失败的结算测试，并确保可以成功运行有关结算的测试套件</span></span></code></pre></div><p>Kimi Code 可以检查测试输出、修改文件、重新运行检查，并判断什么时候可以标记为「完成（<code>complete</code>）」状态。</p></li><li><p>对可能需要多个轮次调查和修复的任务使用目标模式。</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 找出发行版构建失败的原因，修复最本质的原因，并确认构建通过</span></span></code></pre></div><p>目标描述的是结果，因此当第一条线索不是根因时，Agent 也能调整方向。</p></li><li><p>对无需再次提示、应按顺序持续推进的工作使用目标模式。</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 更新功能实现，补充文档，运行测试，并总结变更文件</span></span></code></pre></div><p>当你已经知道完成前必须存在的检查或产物时，这种写法很有用。</p></li></ol><h3 id="何时不要使用目标模式" tabindex="-1">何时不要使用目标模式 <a class="header-anchor" href="#何时不要使用目标模式" aria-label="Permalink to “何时不要使用目标模式”">​</a></h3><ol><li><p>不要把目标模式用于宽泛主题或开放式讨论。</p><div class="warning custom-block"><p class="custom-block-title">反例</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 你好！</span></span></code></pre></div></div><p>对于并不构成目标的内容，Agent 会立即把该目标标记为「完成（<code>complete</code>）」状态。</p></li><li><p>不要把目标模式用于已知不可能或无法解决的任务。</p><div class="warning custom-block"><p class="custom-block-title">反例</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 证明</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3。</span></span></code></pre></div></div><p>如果目标看起来不可能或无法解决，Agent 会把它标记为「阻塞（<code>blocked</code>）」状态。</p></li><li><p>不要使用含糊或过于复杂的目标。</p><div class="warning custom-block"><p class="custom-block-title">反例</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 用单个</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HTML</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 文件创建一个电子游戏。</span></span></code></pre></div></div><p>Agent 有可能会完成该目标，但也可能在等待很久之后产出出人意料的结果。</p></li></ol><h2 id="管理生命周期" tabindex="-1">管理生命周期 <a class="header-anchor" href="#管理生命周期" aria-label="Permalink to “管理生命周期”">​</a></h2><p>使用同一组命令查看或控制当前目标：</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/goal</code> 或 <code>/goal status</code></td><td>显示当前目标及其进展</td></tr><tr><td><code>/goal pause</code></td><td>暂停当前的目标，但不删除</td></tr><tr><td><code>/goal resume</code></td><td>继续被暂停或被阻塞的目标</td></tr><tr><td><code>/goal cancel</code></td><td>移除当前目标</td></tr><tr><td><code>/goal replace &lt;objective&gt;</code></td><td>用新目标替换当前目标</td></tr></tbody></table><p>目标有三种停止方式：</p><ul><li><strong>完成（<code>complete</code>）</strong>：目标已完成，Kimi Code 会清除该目标，Agent 会总结它如何完成了这项工作</li><li><strong>暂停（<code>paused</code>）</strong>：你暂停了它、中断了当前轮次、恢复了原本有目标的会话，或遇到模型、供应商或运行时错误</li><li><strong>阻塞（<code>blocked</code>）</strong>：Kimi Code 需要输入、无法按当前表述完成目标，或达到预算上限。当 Agent 将目标标记为阻塞时，它会写一条简短消息说明原因。</li></ul><p>停止条件需要写在目标本身里。<code>/goal</code> 没有单独用于描述停止限制的语法。</p><h2 id="在-web-界面中管理目标" tabindex="-1">在 Web 界面中管理目标 <a class="header-anchor" href="#在-web-界面中管理目标" aria-label="Permalink to “在 Web 界面中管理目标”">​</a></h2><p>Web 界面会在对话下方显示当前目标条。点击目标条可以展开或收起详细信息。配置 token 预算时，标题栏会显示预算进度；没有配置 token 预算的目标不会显示进度条。</p><p>使用目标条中的操作可以暂停进行中的目标、继续已暂停或已阻塞的目标，或取消当前目标。点击继续会启动下一轮目标工作，Agent 会继续处理该目标。取消操作需要确认，因为取消后无法继续。</p><h2 id="安排后续目标" tabindex="-1">安排后续目标 <a class="header-anchor" href="#安排后续目标" aria-label="Permalink to “安排后续目标”">​</a></h2><p>Agent 有时会很快完成一个目标。如果一次只能安排一个目标，用户可能会失望。很多人已经知道接下来想完成哪些后续目标，但原来需要等当前目标完成后，打开 TUI，再手动提交下一个目标。</p><p>如果已经准备好更多工作，但不想中断当前目标，使用 <code>/goal next</code>：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> next</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 测试通过后更新发布说明</span></span></code></pre></div><p>当前目标运行期间，安排的后续目标对 Agent 不可见。当前目标完成后，Kimi Code 会用与 <code>/goal &lt;objective&gt;</code> 相同的效果开始第一个后续目标。</p><p>如果当前没有目标，<code>/goal next &lt;objective&gt;</code> 会立即开始这个目标。它的效果与 <code>/goal &lt;objective&gt;</code> 相同，并会在目标开始前显示一条状态消息。</p><p>交互式管理后续目标：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> next</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage</span></span></code></pre></div><p>在管理器中，用 <kbd>↑</kbd> / <kbd>↓</kbd> 浏览，<kbd>Space</kbd> 选择一个目标以便移动，选中后用 <kbd>↑</kbd> / <kbd>↓</kbd> 调整顺序，<kbd>E</kbd> 编辑，<kbd>D</kbd> 删除，<kbd>Esc</kbd> 取消。编辑时，用 <kbd>Shift-Enter</kbd> 或 <kbd>Ctrl-J</kbd> 添加新行，用 <kbd>Enter</kbd> 保存。</p><p>如果当前目标被暂停、取消或阻塞，Kimi Code 不会开始下一个后续目标。当目标进入「阻塞（<code>blocked</code>）」状态且存在后续目标时，TUI 会提醒你，这些后续目标会等待当前目标完成。</p><h2 id="谨慎使用目标模式" tabindex="-1">谨慎使用目标模式 <a class="header-anchor" href="#谨慎使用目标模式" aria-label="Permalink to “谨慎使用目标模式”">​</a></h2><p>目标模式适合能通过文件、测试、命令输出、生成产物或明确报告验证的工作。对于一次性修改或只需要一个答案的问题，普通提示词通常更合适。</p><p>在 <code>manual</code> 权限模式下，目标工作可能会停下来等待工具调用审批。无人值守工作应选择与代码库风险和可运行命令相匹配的权限模式。</p><p>在非交互式 prompt 模式中，只支持创建目标：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/goal 修复 checkout 测试失败&quot;</span></span></code></pre></div><p>Prompt 模式在目标完成时以退出码 <code>0</code> 退出，在目标阻塞时以 <code>3</code> 退出，在目标暂停时以 <code>6</code> 退出。<code>/goal next</code> 和其它管理命令都是 TUI 控制命令。</p>`,40)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};